"""
web/embedded.py — Embedded In-Memory Frontend for DRMT V2.
Stores compressed HTML, CSS, and JSX assets directly in Python memory.
Enables running the application with zero external web asset files.
"""

import os
import zlib
import base64
from typing import Dict
from aiohttp import web
from utils.paths import get_bundle_dir

_EMBEDDED_INDEX_HTML = ""
_EMBEDDED_STYLE_CSS = ""
_EMBEDDED_APP_JSX = ""

_cache: Dict[str, str] = {}

def get_embedded_asset(filename: str) -> str:
    """
    Returns the frontend asset.
    If the file exists on disk (e.g. during live frontend development), it reads from disk.
    Otherwise, it decodes and serves the embedded in-memory asset.
    """
    disk_path = os.path.join(get_bundle_dir(), "web", filename)
    if os.path.exists(disk_path):
        try:
            with open(disk_path, "r", encoding="utf-8") as fh:
                return fh.read()
        except Exception:
            pass

    if filename in _cache:
        return _cache[filename]

    if filename == "index.html":
        decompressed = zlib.decompress(base64.b64decode(_EMBEDDED_INDEX_HTML)).decode("utf-8")
    elif filename == "style.css":
        decompressed = zlib.decompress(base64.b64decode(_EMBEDDED_STYLE_CSS)).decode("utf-8")
    elif filename == "app.jsx":
        decompressed = zlib.decompress(base64.b64decode(_EMBEDDED_APP_JSX)).decode("utf-8")
    else:
        decompressed = ""

    _cache[filename] = decompressed
    return decompressed

async def handle_index(request: web.Request) -> web.Response:
    content = get_embedded_asset("index.html")
    return web.Response(text=content, content_type="text/html", headers={"Cache-Control": "no-cache"})

async def handle_css(request: web.Request) -> web.Response:
    content = get_embedded_asset("style.css")
    return web.Response(text=content, content_type="text/css", headers={"Cache-Control": "public, max-age=3600"})

async def handle_jsx(request: web.Request) -> web.Response:
    content = get_embedded_asset("app.jsx")
    return web.Response(text=content, content_type="application/javascript", headers={"Cache-Control": "no-cache"})

def setup_embedded_frontend(app: web.Application) -> None:
    """Registers in-memory frontend routes with aiohttp."""
    app.router.add_get("/", handle_index)
    app.router.add_get("/index.html", handle_index)
    app.router.add_get("/style.css", handle_css)
    app.router.add_get("/app.jsx", handle_jsx)
